#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

const int64 MOD = 1000000007;

int64 modPow(int64 base, int64 exp) {
    int64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k;
    int64 w;
    cin >> k >> w;

    vector<int64> fact(k + 1), invFact(k + 1);
    fact[0] = 1;
    for (int i = 1; i <= k; ++i)
        fact[i] = fact[i - 1] * i % MOD;

    invFact[k] = modPow(fact[k], MOD - 2);
    for (int i = k; i >= 1; --i)
        invFact[i - 1] = invFact[i] * i % MOD;

    const int64 invK = modPow(k, MOD - 2);

    auto tailSum = [&](int64 x) -> int64 {
        int limit = static_cast<int>(min<int64>(k, x));
        int64 result = 0;
        int64 falling = 1;
        int64 power = modPow(k, x - 1);

        for (int a = 1; a <= limit; ++a) {
            falling = falling * (k - a + 1) % MOD;
            int64 term = falling * falling % MOD * power % MOD;
            result += term;
            if (result >= MOD) result -= MOD;
            power = power * invK % MOD;
        }

        if (x < k) {
            for (int a = static_cast<int>(x) + 1; a <= k; ++a) {
                int remaining = k - a;
                int64 first = fact[k] * invFact[remaining] % MOD;
                int index = static_cast<int>(remaining + x);
                int64 second = fact[index] * invFact[remaining] % MOD;
                result = (result + first * second) % MOD;
            }
        }

        return result;
    };

    int64 answer = modPow(k, w);
    answer = (answer + tailSum(w) - tailSum(w - 1)) % MOD;
    if (answer < 0) answer += MOD;

    cout << answer << '\n';
    return 0;
}
